def min_cost_transform(A, B):
    from collections import Counter

    # Check if B is a subsequence of A with correct character counts
    count_A = Counter(A)
    count_B = Counter(B)

    for char in count_B:
        if count_B[char] > count_A[char]:
            return -1

    # Find the minimum cost to remove characters
    # We need to keep characters that match B in order
    j = 0  # pointer for B
    keep_indices = []  # indices in A to keep

    for i in range(len(A)):
        if j < len(B) and A[i] == B[j]:
            keep_indices.append(i)
            j += 1

    if j != len(B):
        return -1

    # Calculate cost of removing characters
    # We remove characters not in keep_indices
    cost = 0
    current_index = 1  # 1-indexed position in current string

    for i in range(len(A)):
        if i not in keep_indices:
            cost += current_index
        else:
            current_index += 1

    return cost

