def solve(source, target, original, changed, cost):
    n = len(source)

    if source == target:
        return 0

    # Build conversion graph for each length
    conversions = defaultdict(lambda: defaultdict(lambda: float('inf')))

    for i in range(len(original)):
        orig = original[i]
        chg = changed[i]
        c = cost[i]
        length = len(orig)
        conversions[length][(orig, chg)] = min(conversions[length][(orig, chg)], c)

    # Floyd-Warshall for each length to find shortest paths
    min_cost_map = {}
    for length in conversions:
        # Get all unique strings of this length
        strings = set()
        for (o, c) in conversions[length]:
            strings.add(o)
            strings.add(c)

        string_list = list(strings)
        string_to_idx = {s: i for i, s in enumerate(string_list)}
        m = len(string_list)

        dist = [[float('inf')] * m for _ in range(m)]
        for i in range(m):
            dist[i][i] = 0

        for (o, c), cost_val in conversions[length].items():
            i = string_to_idx[o]
            j = string_to_idx[c]
            dist[i][j] = min(dist[i][j], cost_val)

        for k in range(m):
            for i in range(m):
                for j in range(m):
                    if dist[i][k] + dist[k][j] < dist[i][j]:
                        dist[i][j] = dist[i][k] + dist[k][j]

        min_cost_map[length] = {}
        for i in range(m):
            for j in range(m):
                if dist[i][j] < float('inf'):
                    min_cost_map[length][(string_list[i], string_list[j])] = dist[i][j]

    # DP to find minimum cost to convert source to target
    dp = [float('inf')] * (n + 1)
    dp[0] = 0

    for i in range(n):
        if dp[i] == float('inf'):
            continue

        # Try all possible substring lengths starting at i
        for length in range(1, n - i + 1):
            src_sub = source[i:i+length]
            tgt_sub = target[i:i+length]

            if src_sub == tgt_sub:
                dp[i + length] = min(dp[i + length], dp[i])
            elif length in min_cost_map and (src_sub, tgt_sub) in min_cost_map[length]:
                conversion_cost = min_cost_map[length][(src_sub, tgt_sub)]
                dp[i + length] = min(dp[i + length], dp[i] + conversion_cost)

    return dp[n] if dp[n] < float('inf') else -1

