class SegTree:

    def __init__(self, n: int):
        self.n = 1<<n.bit_length()
        self.tree = [-inf] * (self.n<<1)

    def update(self, idx: int, val: int):
        idx += self.n
        while idx:
            self.tree[idx] = val
            idx >>= 1

    def query(self, l: int, r: int) -> int:
        res = -inf
        l += self.n
        r += self.n
        while r-l > 1:
            if not l&1:
                res = max(res, self.tree[l+1])
            if r&1:
                res = max(res, self.tree[r-1])
            l >>= 1
            r >>= 1
        return res

