    def maximumValueSum(self, board: List[List[int]]) -> int:
        rows, cols = len(board), len(board[0])
        B = []

        for i in range(rows):
            B.extend(
                heapq.nlargest(3, [(board[i][k], 1 << i, 1 << k) for k in range(cols)])
