    def modifiedMatrix(self, matrix: List[List[int]]) -> List[List[int]]:
        col = []
        for i in range(len(matrix[0])):
            temp = 0
            for j in range(len(matrix)):
                if matrix[j][i] > temp:
                    temp = matrix[j][i]
            col.append(temp)
        for i in range(len(matrix)):
            for j in range(len(matrix[0])):
                if matrix[i][j] == -1:
